import { chromium } from '@playwright/test';

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  const results = {};

  // Home 学习园地
  await page.goto('http://127.0.0.1:8095/', { waitUntil: 'domcontentloaded' });
  await page.waitForSelector('.scroll-tabs', { timeout: 20000 });
  await page.waitForTimeout(1000);
  results.home = await page.evaluate(() => {
    const st = [...document.querySelectorAll('.scroll-tabs')].find(el => el.querySelector('.scroll-tab'));
    if (!st) return { found: false };
    const cs = getComputedStyle(st);
    const tabs = [...st.querySelectorAll('.scroll-tab')];
    const tops = tabs.map(t => Math.round(t.getBoundingClientRect().top));
    return {
      found: true,
      flexWrap: cs.flexWrap,
      overflowX: cs.overflowX,
      scrollbarWidth: cs.scrollbarWidth,
      clientWidth: st.clientWidth,
      scrollWidth: st.scrollWidth,
      tabCount: tabs.length,
      distinctRows: new Set(tops).size,
      tops
    };
  });

  // 学习园地 list page
  await page.goto('http://127.0.0.1:8095/#/pages/portal/list/index?type=study', { waitUntil: 'domcontentloaded' });
  await page.waitForSelector('.scroll-tabs', { timeout: 20000 });
  await page.waitForTimeout(1000);
  results.list = await page.evaluate(() => {
    const st = document.querySelector('.scroll-tabs');
    if (!st) return { found: false };
    const cs = getComputedStyle(st);
    const tabs = [...st.children];
    const tops = tabs.map(t => Math.round(t.getBoundingClientRect().top));
    return {
      found: true,
      flexWrap: cs.flexWrap,
      overflowX: cs.overflowX,
      scrollbarWidth: cs.scrollbarWidth,
      clientWidth: st.clientWidth,
      scrollWidth: st.scrollWidth,
      childCount: tabs.length,
      distinctRows: new Set(tops).size,
      tops
    };
  });

  console.log(JSON.stringify(results, null, 2));
  await browser.close();
})().catch(e => { console.error('ERR', e.message); process.exit(1); });
